      tip1Title: '小贴士',
      tip1Text: '身边有人支持、愿意接受帮助，并不是奢侈。这有助于保存精力，让恢复更加循序渐进。',
      section5Body1: '恢复活动可以一步一步来，根据舒适度、精力以及分娩后得到的建议而定。轻柔的动作和日常活动，本身就算是在恢复运动。',
      section5Body2: '对于强度更大的活动，最好循序渐进、不要跳步，并留意任何症状或不适。',
      alertTitle: '留意身体发出的信号',
