      section1Body1: '產後階段緊接著分娩開始，並不只是短短幾天：在接下來的幾週裡，身體、日常節奏和情緒都可能繼續慢慢變化。',
      section1Body2: '「四十天」（quarantaine）是一種傳統說法，常用來形容產後最初幾週的恢復期。它也是個很好的提醒：經歷懷孕和分娩之後，值得放慢腳步，給身體一些時間。',
