      section3Body2: '症狀的強度和持續時間因人而異。重要的是留意它們的變化；如果出現令你擔心或不尋常的變化，請及時尋求建議。',
      section4Body: '產後階段，小而現實的習慣往往比苛刻的安排更有幫助。目標是支援恢復，而不是給自己增加壓力。',
