    finalTipTitle: 'Yeroo si barbaachisu fudhadhu',
    finalTipText: 'Fayyuun dorgommii miti. Suutuma suutuma fuulduratti deemuu, fedhii kee kabajuu fi yeroo barbaachisu deeggarsa gaafachuun tarkaanfiiwwan ijoo dha.',
    disclaimerText: 'Barruun kun odeeffannoo qofaaf; gorsa yaalaa ofii-isaaf ta\'e hin bakkaa bu\'u. Yoo mallattoo guddaa, itti fufu, ykn si yaaddessu qabaatte, ogeessa fayyaa qunnami.',
