    section4Body: 'सुत्केरीपछिको अवधिमा, कडा दिनचर्याभन्दा साना, यथार्थपरक बानीहरू प्रायः बढी मद्दतकारी हुन्छन्। लक्ष्य दबाब नथपी स्वास्थ्यलाभलाई साथ दिनु हो।',
