    section2Body: 'Những ngày đầu có thể rất dồn dập. Nghỉ ngơi, chăm sóc cơ bản và thích nghi với nhịp sống mới thường là những ưu tiên. Không cần phải lấy lại ngay mức năng lượng thông thường.',
