    section2Body: 'İlk günlər gərgin ola bilər. İstirahət, əsas qayğı və yeni ritmə uyğunlaşma çox vaxt prioritetlərdir. Adi enerji səviyyənizi dərhal bərpa etməyə ehtiyac yoxdur.',
