    section4Body: 'Doğuşdan sonrakı dövrdə kiçik, real vərdişlər çox vaxt tələbkar rejimdən daha faydalıdır. Məqsəd əlavə təzyiq yaratmadan bərpanı dəstəkləməkdir.',
