    section1Body1: 'Հետծննդյան շրջանը հաջորդում է ծննդաբերությանը: Այն չի սահմանափակվում մի քանի օրով. մարմինը, առօրյա ռիթմը և հույզերը կարող են շարունակել աստիճանաբար փոխվել հաջորդ շաբաթների ընթացքում:',
