    section2Body: 'Առաջին օրերը կարող են լինել ինտենսիվ: Հանգիստը, հիմնական խնամքը և նոր ռիթմին հարմարվելը հաճախ առաջնահերթություններն են: Պետք չէ անմիջապես վերագտնել ձեր սովորական էներգիայի մակարդակը:',
