    section4Body: 'Төрөттөн кийинки мезгилде кичинекей, реалдуу адаттар талап кылган тартипке караганда көбүнчө пайдалуураак. Максат — кошумча кысым түшүрбөстөн калыбына келүүнү колдоо.',
