      'Menyambung semula aktiviti secara beransur-ansur membantu anda menghormati tenaga dan keselesaan anda dengan lebih baik.',
      'Jika anda perasan simptom yang luar biasa, berterusan atau membimbangkan, meminta nasihat ialah langkah yang baik.',
