    finalTipTitle: 'Luangkan masa yang anda perlukan',
    finalTipText: 'Pemulihan bukan perlumbaan. Maju secara beransur-ansur, menghormati keperluan anda dan meminta sokongan apabila perlu sudah merupakan langkah penting.',
    disclaimerText: 'Artikel ini hanya untuk tujuan maklumat dan tidak menggantikan nasihat perubatan yang diperibadikan. Jika anda mengalami simptom yang ketara, berterusan atau membimbangkan, hubungi pengamal penjagaan kesihatan.',
