  so: {
    badge: 'DHALMADA KA DIB • BOGSIIN',
    title: 'Bogsiinta\ndhalmada ka dib',
    metaDuration: '10 daq akhris',
    metaType: 'Hage',
    metaLevel: 'Bilow',
    metaValidated: 'Macluumaad la dib-u-eegay',
    intro: 'Jidhkaagu wuxuu u baahan yahay waqti: waxa caadi ah dhalmada ka dib.',
    contentsTitle: 'Maqaalkan dhexdiisa',
    topics: [
      'Fahamka muddada dhalmada ka dib',
      'Maalmaha ugu horreeya: gaabinta iyo bogsiinta',
      'Waxa caadi noqon kara inta bogsiintu socoto',
      'Naftaada daryeel maalin kasta',
      'Dhaqdhaqaaq iyo dib u bilaabista hawlaha tartiib',
      'Hurdo, daal, iyo nidaamyo cusub',
      'Dareenno dhalmada ka dib',
      'Goorta talo la raadsado',
      'La xiriirka xirfadle caafimaad',
      'Waxa la xasuusto',
    ],
    headings: [
      'Fahamka muddada dhalmada ka dib',
      'Maalmaha ugu horreeya: gaabinta iyo bogsiinta',
      'Waxa caadi noqon kara inta bogsiintu socoto',
      'Naftaada daryeel maalin kasta',
      'Dhaqdhaqaaq iyo dib u bilaabista hawlaha tartiib',
      'Hurdo, daal, iyo nidaamyo cusub',
      'Dareenno dhalmada ka dib',
      'Goorma talo la raadsadaa?',
      'La xiriirka xirfadle caafimaad',
      'Waxa la xasuusto',
    ],
    section1Body1: 'Muddada dhalmada ka dib waxay raacdaa dhalmada. Kuma koobna dhowr maalmood: jidhka, xawaaraha maalinlaha ah, iyo dareennada way sii isbeddeli karaan tartiib toddobaadyada xiga.',
    section1Body2: '“Quarantaine” waa hadal dhaqan ah oo inta badan loo isticmaalo sharraxaadda toddobaadyada ugu horreeya ee bogsiinta. Waxay u adeegi kartaa xasuusin wanaagsan: uurka iyo dhalmada ka dib, waa mudan in la gaabiyo oo jidhka la siiyo waqti.',
    highlight1Title: 'Bogsiin jidhka oo dhan ah',
    highlight1Text: 'Bogsiintu waxay khusaysaa jidhka, laakiin sidoo kale hurdada, tamarta, habaynta maalinlaha ah, iyo la qabsiga dareenka heerka cusub ee nolosha.',
    section2Body: 'Maalmaha ugu horreeya waxay noqon karaan kuwo xoog badan. Nasasho, daryeel aasaasi ah, iyo la qabsiga xawaaraha cusub inta badan waa mudnaanta. Looma baahna inaad isla markiiba dib u hesho heerka tamarta ee caadiga ah.',
    recoveryPillars: [
      {title: 'Nasasho', text: 'Beddelidda firfircoonida iyo nasashada ayaa caawisa jidhka inuu tartiib u bogsado.'},
      {title: 'Nafaqo', text: 'Cunista si joogto ah iyo cabbidda iyadoo loo eegayo baahidaada ayaa taageerta bogsiinta maalinlaha ah.'},
      {title: 'Taageero', text: 'Aqbalidda caawimaad waxay suurtogelisaa badbaadinta tamarta daryeelka lagama maarmaanka ah iyo bogsiinta.'},
      {title: 'Dhaqdhaqaaq jilicsan', text: 'Tartiib u bilow dhaqdhaqaaqyada iyo hawlaha, adigoo ixtiraamaya xaaladdaada iyo raaxadaada.'},
    ],
    section3Body1: 'Bogsiin kastaa waa ka duwan tahay. Isbeddelo qaar ayaa ka mid noqon kara muddada la qabsiga oo tartiib u isbeddeli kara:',
    normalSigns: [
      'Daal weyn',
      'Dhiigbax tartiib u yaraada',
      'Isbeddelo hormoon iyo dareen',
    ],
    section3Body2: 'Xoogga iyo muddada astaamuhu way ku kala duwanaan karaan qof ilaa qof. Waxa muhiimka ah waa indho-indheynta sida ay u isbeddelaan iyo raadinta talo haddii isbeddel uu u muuqdo mid walaac leh ama aan caadi ahayn.',
    section4Body: 'Inta lagu jiro muddada dhalmada ka dib, caadooyin yaryar, oo dhab ah inta badan way ka faa’iido badan yihiin nidaam adag. Ujeeddadu waa in la taageero bogsiinta iyadoo aan cadaadis dheeraad ah lagu darin.',
    selfCareTips: [
      'Qorshee wakhtiyo nasasho oo dhab ah marka ay suurtagal tahay.',
      'Weydiiso caawimaad hawlaha maalinlaha ah iyo cuntada.',
      'Cab si joogto ah oo hay cunto kala duwan.',
      'Ka fogow barbar dhigidda bogsiintaada tan qof kale.',
      'Tartiib u bilow hawlaha, adigoon isku dayin inaad wax walba isla markiiba sameyso.',
    ],
    tip1Title: 'Waxtar leh in la ogaado',
    tip1Text: 'Ku wareejinta naftaada taageero iyo aqbalidda caawimaad ma aha raaxo. Waxay caawin kartaa ilaalinta tamarta oo ka dhigi karta bogsiinta mid tartiib ah.',
    section5Body1: 'Dib u bilaabista hawlaha waxay dhici kartaa tallaabo tallaabo, iyadoo ku salaysan raaxada, tamarta, iyo talooyinka la helay dhalmada ka dib. Dhaqdhaqaaqyo jilicsan iyo hawlo maalinle ah horey ayay u tiriyaan sida ku laabasho dhaqdhaqaaq.',
    section5Body2: 'Hawlaha ka xoog badan, waxaa ugu wanaagsan in la horumariyo adigoon tallaabooyin hakin oo la tixgeliyo astaamo ama raaxo-darro kasta.',
    alertTitle: 'U dhegeyso calaamadaha jidhkaaga',
    alertText: 'Raaxo-darro kordhaysa inta hawl socoto waa sabab ah in la gaabiyo oo, haddii loo baahdo, in talo ku habboon la raadsado ka hor intaan la sii wadin ama kordhin xoogga.',
    section6Body: 'Hurdadu way noqon kartaa mid aan joogto ahayn dhalmada ka dib. Daalka la ururiyey wuxuu saameyn karaa tamarta, isku-xidhidda, iyo niyadda. Marka ay suurtagal tahay, fududaynta hawlo qaar iyo wadaagista mas’uuliyadaha ayaa caawin kara.',
    milestones: [
      ['Maalmaha ugu horreeya', 'Nasasho, la qabsi, iyo daryeel lagama maarmaan ah.'],
      ['Toddobaadyada ugu horreeya', 'Bogsiin tartiib ah iyo bilowga nidaamyo cusub.'],
      ['Baaritaanka dhalmada ka dib', 'Dib u eeg horumarka bogsiinta oo kala hadal dib u bilaabista hawlaha tartiib.'],
    ],
    section7Body1: 'Muddada dhalmada ka dib waxay keeni kartaa dareenno badan: farxad, walaac, daal, dareen-xanaaq, ama dareen xad dhaaf ah. Dareennadani si dhakhso ah ayay isu beddeli karaan, gaar ahaan wakhti hurdada iyo caadooyinka maalinlaha ah ay isbeddelayaan.',
    section7Body2: 'La hadalka qof aad ku kalsoon tahay ama xirfadle ayaa caawin kara marka dareennadu noqdaan kuwo adag in la maamulo ama ay qaadaan meel weyn oo nolol-maalmeedka ah.',
    highlight2Title: 'Weydiisashada taageero waa caadi',
    highlight2Text: 'Looma baahna inaad sugto ilaa aad si buuxda u daallanayso ama aad xad dhaaf u dareento ka hor intaadan ka hadlin sida aad dareemayso oo aad raadsato taageero.',
    section8Body: 'Xaalado qaar ayaa mudan in lala hadlo xirfadle caafimaad, gaar ahaan marka ay xumaadaan, sii socdaan, ama keenaan walaac weyn.',
    consultationSigns: [
      {title: 'Astaamo sii xumaanaya', text: 'Xanuun ama raaxo-darro kordhaysa halkii ay hagaagi lahayd waxay mudan tahay talo xirfadle.'},
      {title: 'Dhiigbax aan caadi ahayn', text: 'Dhiigbax si lama filaan ah u noqda mid ka culus ama aan caadi ahayn waa in loo sheegaa xirfadle caafimaad.'},
      {title: 'Dhib sii socda', text: 'Haddii dhibka dareenku qaado meel weyn ama uu ka dhigo nolol-maalmeedka mid adag, waa muhiim in laga hadlo oo la raadsado taageero.'},
      {title: 'Walaac weyn', text: 'Haddii aad shaki ka qabto bogsiintaada, weydiisashada talo waxay kuu helaysaa talooyin ku habboon xaaladdaada.'},
    ],
    section9Body: 'Ballammada la socodku waa fursad lagu hadlo bogsiinta, astaamaha, dib u bilaabista hawlaha, iyo su’aalo kasta oo harsan. Diyaarinta dhowr su’aalood hore ayaa caawin karta in waxba la illoobin.',
    questionTitle: 'Su’aalaha aad diyaarin karto',
    questions: [
      'Bogsiintaydu ma u socotaa sida la filayo xaaladdayda?',
      'Waa kuwee hawlaha aan tartiib dib u bilaabi karo?',
      'Waa kuwee astaamaha aan indho-indheeyo?',
      'Goorma ayaan ka fikiri karaa ku laabasho layli oo ka xoog badan?',
      'Ma u baahanahay talo gaar ah ama dib-u-habayn?',
    ],
    summaryItems: [
      'Bogsiinta dhalmada ka dib waa mid tartiib ah oo ka duwan qof walba.',
      'Nasasho iyo taageero waxay noqon karaan qayb ka mid ah bogsiinta.',
      'Isbeddelada jidheed, hurdada, iyo dareennadu way isbeddeli karaan toddobaadyada gudahood.',
      'Dib u bilaabista hawlaha tartiib ayaa kaa caawisa inaad si wanaagsan u ixtiraamto tamartaada iyo raaxadaada.',
      'Haddii aad ogaato astaan aan caadi ahayn, sii socota, ama walaac leh, weydiisashada talo waa tallaabo wanaagsan.',
    ],
    finalTipTitle: 'Qaado waqtiga aad u baahan tahay',
    finalTipText: 'Bogsiintu ma aha tartan. U soco tartiib, ixtiraam baahiyahaaga, oo weydiiso taageero marka loo baahdo — kuwani horey ayay u yihiin tallaabooyin muhiim ah.',
    disclaimerText: 'Maqaalkan waa macluumaad oo keliya mana bedelo talo caafimaad oo shakhsi ah. Haddii aad la kulanto astaan weyn, sii socota, ama walaac leh, la xiriir xirfadle caafimaad.',
    shareMessage: 'Bogsiinta dhalmada ka dib — AWA',
  },
