    tip1Title: 'Vyema kujua',
    tip1Text: 'Kujizunguka na msaada na kukubali msaada si anasa. Kunaweza kusaidia kuhifadhi nguvu na kufanya kupona kuwe polepole zaidi.',
    section5Body1: 'Kuanza tena shughuli kunaweza kufanyika hatua kwa hatua, kulingana na faraja, nguvu, na mapendekezo uliyopokea baada ya kujifungua. Mienendo myepesi na shughuli za kila siku tayari zinahesabika kama kurejea kwenye mwendo.',
    section5Body2: 'Kwa shughuli kali zaidi, ni bora kuendelea bila kuruka hatua na kuzingatia dalili au usumbufu wowote.',
    alertTitle: 'Sikiliza ishara za mwili wako',
    alertText: 'Usumbufu unaoongezeka wakati wa shughuli ni sababu ya kupunguza mwendo na, ikihitajika, kutafuta ushauri unaofaa kabla ya kuendelea au kuongeza ukali.',
    section6Body: 'Usingizi unaweza kuwa si wa mpangilio baada ya kujifungua. Uchovu uliorundikana unaweza kuathiri nguvu, uwezo wa kuzingatia, na hali ya moyo. Inapowezekana, kurahisisha kazi fulani na kugawana majukumu kunaweza kusaidia.',
    milestones: [
      ['Siku za kwanza', 'Kupumzika, kuzoea, na huduma muhimu.'],
      ['Wiki za kwanza', 'Kupona polepole na mwanzo wa taratibu mpya.'],
      ['Baada ya ukaguzi wa baada ya kujifungua', 'Pitia maendeleo ya kupona na jadili kuanza tena shughuli polepole.'],
    ],
    section7Body1: 'Kipindi cha baada ya kujifungua kinaweza kuleta hisia nyingi: furaha, wasiwasi, uchovu, unyeti, au hisia ya kuelemewa. Hisia hizi zinaweza kubadilika haraka, hasa wakati ambapo usingizi na tabia za kila siku zinabadilika.',
    section7Body2: 'Kuzungumza na mtu unayemwamini au mtaalamu kunaweza kusaidia hisia zinapokuwa ngumu kudhibiti au zinapochukua nafasi kubwa katika maisha ya kila siku.',
    highlight2Title: 'Kuomba msaada ni jambo la kawaida',
    highlight2Text: 'Hakuna haja ya kusubiri hadi uchoke kabisa au uelemewe kabla ya kuzungumzia unavyojisikia na kutafuta msaada.',
    section8Body: 'Hali fulani zinastahili kujadiliwa na mtaalamu wa afya, hasa zinapozidi kuwa mbaya, kuendelea, au kusababisha wasiwasi mkubwa.',
    consultationSigns: [
      {title: 'Dalili zinazozidi kuwa mbaya', text: 'Maumivu au usumbufu unaoongezeka badala ya kuimarika unastahili ushauri wa kitaalamu.'},
      {title: 'Kutokwa damu kusiko kwa kawaida', text: 'Kutokwa damu kunakokuwa kwingi zaidi ghafla au kusiko kwa kawaida kunapaswa kuripotiwa kwa mtaalamu wa afya.'},
      {title: 'Dhiki ya kuendelea', text: 'Dhiki ya kihisia ikichukua nafasi kubwa au kufanya maisha ya kila siku kuwa magumu, ni muhimu kuzungumzia na kuomba msaada.'},
      {title: 'Wasiwasi mkubwa', text: 'Ukiwa na shaka kuhusu kupona kwako, kuomba ushauri kunakusaidia kupata mapendekezo yanayofaa hali yako.'},
    ],
    section9Body: 'Miadi ya ufuatiliaji ni fursa ya kuzungumzia kupona, dalili, kuanza tena shughuli, na maswali yoyote yaliyobaki. Kuandaa maswali machache mapema kunaweza kusaidia kuhakikisha hakuna kinachosahaulika.',
