    section1Body1: 'Босанғаннан кейінгі кезең босанудан кейін келеді. Ол бірнеше күнмен шектелмейді: дене, күнделікті ырғақ және эмоциялар келесі апталарда біртіндеп өзгеруін жалғастыра алады.',
    section1Body2: '“Карантин” (quarantaine) — қалпына келудің алғашқы апталарын сипаттау үшін жиі қолданылатын дәстүрлі өрнек. Ол жақсы еске салғыш бола алады: жүктілік пен босанудан кейін баяулап, денеге уақыт беру жөн.',
