    section2Body: 'Алғашқы күндер қарқынды болуы мүмкін. Демалыс, негізгі күтім және жаңа ырғаққа бейімделу көбіне басымдықтар болады. Әдеттегі қуат деңгейіңізге бірден оралудың қажеті жоқ.',
