    section3Body2: 'Белгілердің қарқындылығы мен ұзақтығы әр адамда әртүрлі болуы мүмкін. Маңыздысы — олардың қалай дамитынын бақылау және өзгеріс алаңдатарлық немесе әдеттен тыс болса, кеңес сұрау.',
    section4Body: 'Босанғаннан кейінгі кезеңде шағын, шынайы әдеттер көбіне талапшыл тәртіптен пайдалырақ. Мақсат — қосымша қысым қоспай, қалпына келуді қолдау.',
