    section5Body1: 'Белсенділікті қайта бастау жайлылыққа, қуатқа және босанғаннан кейін алынған ұсыныстарға қарай қадам-қадаммен болуы мүмкін. Жұмсақ қозғалыстар мен күнделікті әрекеттер қазірдің өзінде қозғалысқа оралу болып саналады.',
    section5Body2: 'Қарқындырақ белсенділік үшін қадамдарды өткізбей алға жылжып, кез келген белгі немесе жайсыздықты ескерген жөн.',
