    tip1Title: 'Abin da ya dace a sani',
    tip1Text: 'Kewaye kanki da tallafi da karɓar taimako ba abin more rayuwa ba ne. Yana iya taimakawa wajen adana kuzari da sa murmurewa ya zama a hankali.',
    section5Body1: 'Komawa ayyuka na iya faruwa mataki-mataki, bisa jin daɗi, kuzari, da shawarwarin da aka karɓa bayan haihuwa. Motsi masu laushi da ayyukan yau da kullum sun riga sun ƙidaya a matsayin komawa motsi.',
    section5Body2: 'Ga ayyuka masu tsanani, ya fi kyau a ci gaba ba tare da tsallake matakai ba kuma a yi la’akari da duk wata alama ko rashin jin daɗi.',
    alertTitle: 'Saurari alamomin jikinki',
    alertText: 'Rashin jin daɗi da ke ƙaruwa yayin aiki dalili ne na rage gudu kuma, idan ya zama dole, a nemi shawara da ta dace kafin a ci gaba ko ƙara ƙarfi.',
    section6Body: 'Barci na iya zama mara tsari bayan haihuwa. Tarin gajiya na iya shafar kuzari, mai da hankali, da yanayi. Idan zai yiwu, sauƙaƙa wasu ayyuka da rarraba nauyi na iya taimakawa.',
    milestones: [
      ['Kwanakin farko', 'Hutu, daidaitawa, da kulawa ta asali.'],
      ['Makonni na farko', 'Murmurewa a hankali da farkon sabbin tsare-tsare.'],
      ['Bayan duba lafiya na bayan haihuwa', 'Duba ci gaban murmurewa da tattauna komawa ayyuka a hankali.'],
    ],
    section7Body1: 'Lokacin bayan haihuwa na iya kawo ji da yawa: farin ciki, damuwa, gajiya, hankali, ko jin cewa an cika miki nauyi. Waɗannan ji na iya canzawa da sauri, musamman a lokacin da barci da dabi’u na yau da kullum ke canzawa.',
    section7Body2: 'Magana da wanda kike amincewa da shi ko ƙwararre na iya taimakawa idan ji ya zama da wuyar sarrafawa ko ya mamaye sarari mai yawa a rayuwar yau da kullum.',
    highlight2Title: 'Neman tallafi al’ada ne',
    highlight2Text: 'Babu bukatar jira har sai kin gaji gaba ɗaya ko an cika miki nauyi kafin ki yi magana game da yadda kike ji ki nemi tallafi.',
    section8Body: 'Wasu yanayi sun cancanci a tattauna da ma’aikacin lafiya, musamman idan sun ƙara muni, sun dawwama, ko sun haifar da damuwa mai yawa.',
