    section1Body1: 'De postpartumperiode volgt op de bevalling. Ze is niet beperkt tot een paar dagen: het lichaam, het dagelijkse ritme en de emoties kunnen zich in de weken daarna geleidelijk blijven ontwikkelen.',
    section1Body2: 'De “quarantaine” is een traditionele uitdrukking die vaak wordt gebruikt om de eerste weken van herstel te beschrijven. Ze kan dienen als goede herinnering: na zwangerschap en bevalling is het zinvol te vertragen en het lichaam de tijd te geven.',
    highlight1Title: 'Een herstel van het hele lichaam',
    highlight1Text: 'Het herstel betreft het lichaam, maar ook slaap, energie, dagelijkse organisatie en de emotionele aanpassing aan een nieuwe levensfase.',
    section2Body: 'De eerste dagen kunnen intens zijn. Rust, basiszorg en wennen aan het nieuwe ritme zijn vaak de prioriteiten. Je hoeft niet meteen je gebruikelijke energieniveau terug te krijgen.',
    recoveryPillars: [
      {title: 'Rust', text: 'Activiteit en rust afwisselen helpt het lichaam geleidelijk te herstellen.'},
      {title: 'Voeding', text: 'Regelmatig eten en drinken naargelang je behoeften ondersteunt het herstel van dag tot dag.'},
      {title: 'Steun', text: 'Hulp aanvaarden maakt het mogelijk energie te sparen voor essentiële zorg en herstel.'},
      {title: 'Zachte beweging', text: 'Hervat bewegingen en activiteiten geleidelijk, met respect voor je toestand en comfort.'},
    ],
    section3Body1: 'Elk herstel is anders. Sommige veranderingen kunnen deel uitmaken van de aanpassingsperiode en zich geleidelijk ontwikkelen:',
