    section9Body: 'Opvolgafspraken zijn een gelegenheid om te praten over het herstel, klachten, het hervatten van activiteiten en eventuele resterende vragen. Vooraf een paar vragen voorbereiden kan helpen ervoor te zorgen dat niets wordt vergeten.',
