    section1Body1: 'Synnytyksen jälkeinen aika seuraa synnytystä. Se ei rajoitu muutamaan päivään: keho, päivittäinen rytmi ja tunteet voivat jatkaa kehittymistään vähitellen seuraavien viikkojen aikana.',
    section1Body2: '“Quarantaine” on perinteinen ilmaus, jolla usein kuvataan ensimmäisiä toipumisviikkoja. Se voi toimia hyvänä muistutuksena: raskauden ja synnytyksen jälkeen on järkevää hidastaa ja antaa keholle aikaa.',
    highlight1Title: 'Koko kehon toipuminen',
    highlight1Text: 'Toipuminen koskee kehoa, mutta myös unta, energiaa, päivittäistä järjestelyä ja henkistä sopeutumista uuteen elämänvaiheeseen.',
    section2Body: 'Ensimmäiset päivät voivat olla intensiivisiä. Lepo, perushoito ja sopeutuminen uuteen rytmiin ovat usein prioriteetteja. Tavanomaista energiatasoa ei tarvitse saada heti takaisin.',
