    tip1Title: 'Hyvä tietää',
    tip1Text: 'Tuen ympärillesi hankkiminen ja avun vastaanottaminen ei ole ylellisyyttä. Se voi auttaa säästämään energiaa ja tehdä toipumisesta asteittaisempaa.',
    section5Body1: 'Toimintojen jatkaminen voi tapahtua askel kerrallaan mukavuuden, energian ja synnytyksen jälkeen saatujen suositusten mukaan. Lempeät liikkeet ja arkiset toiminnot lasketaan jo paluuksi liikkumiseen.',
    section5Body2: 'Intensiivisempien toimintojen osalta on parasta edetä ohittamatta vaiheita ja ottaa huomioon mahdolliset oireet tai epämukavuus.',
    alertTitle: 'Kuuntele kehosi signaaleja',
    alertText: 'Epämukavuus, joka lisääntyy toiminnan aikana, on syy hidastaa ja tarvittaessa pyytää räätälöityä neuvoa ennen jatkamista tai voimakkuuden lisäämistä.',
    section6Body: 'Uni voi muuttua epäsäännölliseksi synnytyksen jälkeen. Kertynyt väsymys voi vaikuttaa energiaan, keskittymiseen ja mielialaan. Mahdollisuuksien mukaan tiettyjen tehtävien yksinkertaistaminen ja vastuiden jakaminen voi auttaa.',
    milestones: [
      ['Ensimmäiset päivät', 'Lepo, sopeutuminen ja olennainen hoito.'],
      ['Ensimmäiset viikot', 'Asteittainen toipuminen ja uusien rutiinien alku.'],
      ['Synnytyksen jälkitarkastuksen jälkeen', 'Käy läpi toipumisen eteneminen ja keskustele toimintojen asteittaisesta jatkamisesta.'],
    ],
    section7Body1: 'Synnytyksen jälkeinen aika voi tuoda mukanaan monia tunteita: iloa, huolta, väsymystä, herkkyyttä tai uuvuksissa olemisen tunnetta. Nämä tunteet voivat vaihtua nopeasti, erityisesti aikana, jolloin uni ja päivittäiset tavat muuttuvat.',
    section7Body2: 'Luottamasi ihmisen tai ammattilaisen kanssa puhuminen voi auttaa, kun tunteet käyvät vaikeiksi hallita tai vievät paljon tilaa arjessa.',
    highlight2Title: 'Tuen pyytäminen on normaalia',
    highlight2Text: 'Sinun ei tarvitse odottaa, kunnes olet täysin uupunut tai ylikuormittunut, ennen kuin puhut tuntemuksistasi ja haet tukea.',
    section8Body: 'Joistakin tilanteista on hyvä keskustella terveydenhuollon ammattilaisen kanssa, erityisesti kun ne pahenevat, jatkuvat tai aiheuttavat merkittävää huolta.',
