    section9Body: 'Seurantakäynnit ovat tilaisuus puhua toipumisesta, oireista, toimintojen jatkamisesta ja mahdollisista muista kysymyksistä. Muutaman kysymyksen valmistelu etukäteen voi auttaa varmistamaan, ettei mitään unohdu.',
