    section5Body1: 'Η επανέναρξη των δραστηριοτήτων μπορεί να γίνεται βήμα βήμα, ανάλογα με την άνεση, την ενέργεια και τις συστάσεις που έλαβες μετά τον τοκετό. Οι ήπιες κινήσεις και οι καθημερινές δραστηριότητες μετρούν ήδη ως επιστροφή στην κίνηση.',
    section5Body2: 'Για πιο έντονες δραστηριότητες, είναι καλύτερα να προχωράς χωρίς να παραλείπεις στάδια και να λαμβάνεις υπόψη τυχόν συμπτώματα ή δυσφορία.',
