    section6Body: 'Ο ύπνος μπορεί να γίνει ακανόνιστος μετά τον τοκετό. Η συσσωρευμένη κόπωση μπορεί να επηρεάσει την ενέργεια, τη συγκέντρωση και τη διάθεση. Όταν είναι δυνατό, η απλοποίηση ορισμένων εργασιών και ο διαμοιρασμός των ευθυνών μπορεί να βοηθήσει.',
