    section9Body: 'Τα ραντεβού παρακολούθησης είναι μια ευκαιρία να μιλήσεις για την ανάρρωση, τα συμπτώματα, την επανέναρξη δραστηριοτήτων και τυχόν εκκρεμείς ερωτήσεις. Το να προετοιμάσεις μερικές ερωτήσεις εκ των προτέρων μπορεί να βοηθήσει να μην ξεχαστεί τίποτα.',
