    section1Body1: 'Sumusunod sa panganganak ang panahon pagkatapos manganak. Hindi ito limitado sa ilang araw: maaaring patuloy na unti-unting magbago ang katawan, pang-araw-araw na ritmo, at mga emosyon sa mga susunod na linggo.',
    section1Body2: 'Ang “quarantaine” ay tradisyonal na pananalitang madalas gamitin para ilarawan ang unang mga linggo ng paggaling. Maaari itong magsilbing mabuting paalala: pagkatapos ng pagbubuntis at panganganak, sulit na magdahan-dahan at bigyan ng oras ang katawan.',
    highlight1Title: 'Isang paggaling ng buong katawan',
    highlight1Text: 'Nauukol ang paggaling sa katawan, ngunit pati na rin sa tulog, enerhiya, pang-araw-araw na pag-aayos, at sa emosyonal na pag-angkop sa bagong yugto ng buhay.',
    section2Body: 'Maaaring maging matindi ang unang mga araw. Madalas na pahinga, pangunahing pag-aalaga, at pag-angkop sa bagong ritmo ang mga priyoridad. Hindi na kailangang agad mabawi ang karaniwan mong antas ng enerhiya.',
