    section3Body2: 'Maaaring mag-iba sa bawat tao ang tindi at tagal ng mga sintomas. Ang mahalaga ay bantayan kung paano sila nagbabago at humingi ng payo kung tila nakababahala o hindi pangkaraniwan ang pagbabago.',
    section4Body: 'Sa panahon pagkatapos manganak, madalas na mas nakakatulong ang maliliit at makatotohanang mga gawi kaysa sa mahigpit na routine. Layunin na suportahan ang paggaling nang walang dagdag na pressure.',
