    section5Body1: 'Maaaring ipagpatuloy nang hakbang-hakbang ang mga gawain, batay sa ginhawa, enerhiya, at mga rekomendasyong natanggap pagkatapos manganak. Ang banayad na mga galaw at pang-araw-araw na gawain ay itinuturing nang pagbabalik sa paggalaw.',
    section5Body2: 'Para sa mas matinding mga gawain, pinakamainam na umusad nang hindi nilalaktawan ang mga hakbang at isaalang-alang ang anumang sintomas o kakulangan sa ginhawa.',
