    section7Body1: 'Ang panahon pagkatapos manganak ay maaaring magdala ng maraming emosyon: saya, pag-aalala, pagod, pagiging sensitibo, o pakiramdam na nalulula. Mabilis na maaaring magbago ang mga damdaming ito, lalo na sa panahong nagbabago ang tulog at pang-araw-araw na gawi.',
    section7Body2: 'Ang pakikipag-usap sa taong pinagkakatiwalaan mo o sa propesyonal ay makakatulong kapag nagiging mahirap pangasiwaan ang mga emosyon o kumukuha ng malaking espasyo sa pang-araw-araw na buhay.',
