    section1Body1: 'પ્રસૂતિ પછીનો સમય પ્રસૂતિ બાદ શરૂ થાય છે. તે થોડા દિવસો પૂરતો મર્યાદિત નથી: શરીર, રોજિંદી લય અને લાગણીઓ પછીના અઠવાડિયાઓમાં ધીમે ધીમે બદલાતી રહી શકે છે.',
    section1Body2: 'ચિલ્લા એ પરંપરાગત શબ્દ છે, જે ઘણી વાર સ્વસ્થતાના શરૂઆતના અઠવાડિયાઓ માટે વપરાય છે. તે એક સારું સ્મરણ બની શકે: ગર્ભાવસ્થા અને પ્રસૂતિ પછી ધીમા પડવું અને શરીરને સમય આપવો યોગ્ય છે.',
