    section2Body: 'શરૂઆતના દિવસો તીવ્ર હોઈ શકે. આરામ, મૂળભૂત સંભાળ અને નવી લય સાથે ગોઠવાવું ઘણી વાર પ્રાથમિકતા હોય છે. તરત જ તમારી સામાન્ય શક્તિ પાછી મેળવવાની જરૂર નથી.',
