    section4Body: 'પ્રસૂતિ પછીના સમયમાં, મુશ્કેલ દિનચર્યા કરતાં નાની, વાસ્તવિક ટેવો ઘણી વાર વધુ ઉપયોગી હોય છે. લક્ષ્ય દબાણ ઉમેર્યા વિના સ્વસ્થતાને સહારો આપવાનું છે.',
