    section7Body1: 'પ્રસૂતિ પછીનો સમય ઘણી લાગણીઓ લાવી શકે: આનંદ, ચિંતા, થાક, સંવેદનશીલતા કે અભિભૂત થઈ જવાની લાગણી. આ લાગણીઓ ઝડપથી બદલાઈ શકે, ખાસ કરીને જ્યારે ઊંઘ અને રોજિંદી ટેવો બદલાતી હોય.',
    section7Body2: 'જ્યારે લાગણીઓ સંભાળવી મુશ્કેલ બને અથવા રોજિંદા જીવનમાં ઘણી જગ્યા રોકે, ત્યારે તમે વિશ્વાસ કરતા હો તેવી વ્યક્તિ સાથે કે વ્યાવસાયિક સાથે વાત કરવાથી મદદ મળી શકે.',
    highlight2Title: 'સહારો માગવો સામાન્ય છે',
    highlight2Text: 'તમને કેવું લાગે છે તે વિશે વાત કરવા અને સહારો લેવા માટે સંપૂર્ણ થાકી જવાની કે અભિભૂત થઈ જવાની રાહ જોવાની જરૂર નથી.',
    section8Body: 'કેટલીક પરિસ્થિતિઓ વિશે આરોગ્ય વ્યાવસાયિક સાથે વાત કરવી યોગ્ય છે, ખાસ કરીને જ્યારે તે વધુ ખરાબ થાય, ચાલુ રહે કે ઘણી ચિંતા કરાવે.',
