    section9Body: 'ફોલો-અપ મુલાકાતો સ્વસ્થતા, લક્ષણો, પ્રવૃત્તિઓ ફરી શરૂ કરવી અને બાકી રહેલા પ્રશ્નો વિશે વાત કરવાની તક છે. અગાઉથી થોડા પ્રશ્નો તૈયાર રાખવાથી કશું ભુલાય નહીં તેની ખાતરી થઈ શકે.',
