      'ਸਭ ਕੁਝ ਇੱਕਦਮ ਕਰਨ ਦੀ ਕੋਸ਼ਿਸ਼ ਕੀਤੇ ਬਿਨਾਂ ਹੌਲੀ-ਹੌਲੀ ਕੰਮ ਮੁੜ ਸ਼ੁਰੂ ਕਰੋ।',
