    tip1Title: 'ਜਾਣਨ ਯੋਗ',
    tip1Text: 'ਆਪਣੇ ਆਲੇ-ਦੁਆਲੇ ਸਹਾਰਾ ਰੱਖਣਾ ਅਤੇ ਮਦਦ ਲੈਣਾ ਕੋਈ ਐਸ਼ ਨਹੀਂ ਹੈ। ਇਹ ਤਾਕਤ ਬਚਾਉਣ ਅਤੇ ਸਿਹਤਯਾਬੀ ਨੂੰ ਹੋਰ ਹੌਲੀ-ਹੌਲੀ ਬਣਾਉਣ ਵਿੱਚ ਮਦਦ ਕਰ ਸਕਦਾ ਹੈ।',
    section5Body1: 'ਕੰਮ ਮੁੜ ਸ਼ੁਰੂ ਕਰਨਾ ਕਦਮ-ਦਰ-ਕਦਮ ਹੋ ਸਕਦਾ ਹੈ, ਆਰਾਮ, ਤਾਕਤ ਅਤੇ ਜਣੇਪੇ ਤੋਂ ਬਾਅਦ ਮਿਲੀਆਂ ਸਿਫ਼ਾਰਸ਼ਾਂ ਦੇ ਆਧਾਰ ਉੱਤੇ। ਹਲਕੀਆਂ ਹਰਕਤਾਂ ਅਤੇ ਰੋਜ਼ਾਨਾ ਦੇ ਕੰਮ ਵੀ ਹਰਕਤ ਵੱਲ ਵਾਪਸੀ ਗਿਣੇ ਜਾਂਦੇ ਹਨ।',
    section5Body2: 'ਵਧੇਰੇ ਜ਼ੋਰ ਵਾਲੇ ਕੰਮਾਂ ਲਈ, ਕਦਮ ਛੱਡੇ ਬਿਨਾਂ ਅੱਗੇ ਵਧਣਾ ਅਤੇ ਕਿਸੇ ਵੀ ਲੱਛਣ ਜਾਂ ਬੇਆਰਾਮੀ ਨੂੰ ਧਿਆਨ ਵਿੱਚ ਰੱਖਣਾ ਬਿਹਤਰ ਹੈ।',
    alertTitle: 'ਆਪਣੇ ਸਰੀਰ ਦੇ ਸੰਕੇਤ ਸੁਣੋ',
    alertText: 'ਜੇ ਕਿਸੇ ਕੰਮ ਦੌਰਾਨ ਬੇਆਰਾਮੀ ਵਧਦੀ ਹੈ, ਤਾਂ ਰਫ਼ਤਾਰ ਹੌਲੀ ਕਰਨ ਦਾ ਕਾਰਨ ਹੈ, ਅਤੇ ਲੋੜ ਪੈਣ ਉੱਤੇ ਜਾਰੀ ਰੱਖਣ ਜਾਂ ਜ਼ੋਰ ਵਧਾਉਣ ਤੋਂ ਪਹਿਲਾਂ ਆਪਣੇ ਹਿਸਾਬ ਨਾਲ ਸਲਾਹ ਲੈਣੀ ਚਾਹੀਦੀ ਹੈ।',
    section6Body: 'ਜਣੇਪੇ ਤੋਂ ਬਾਅਦ ਨੀਂਦ ਬੇਨਿਯਮੀ ਵਾਲੀ ਹੋ ਸਕਦੀ ਹੈ। ਜਮ੍ਹਾਂ ਹੋਈ ਥਕਾਵਟ ਤਾਕਤ, ਧਿਆਨ ਅਤੇ ਮੂਡ ਉੱਤੇ ਅਸਰ ਪਾ ਸਕਦੀ ਹੈ। ਜਦੋਂ ਸੰਭਵ ਹੋਵੇ, ਕੁਝ ਕੰਮਾਂ ਨੂੰ ਸੌਖਾ ਬਣਾਉਣਾ ਅਤੇ ਜ਼ਿੰਮੇਵਾਰੀਆਂ ਵੰਡਣਾ ਮਦਦ ਕਰ ਸਕਦਾ ਹੈ।',
