    section7Body1: 'ਜਣੇਪੇ ਤੋਂ ਬਾਅਦ ਦਾ ਸਮਾਂ ਕਈ ਭਾਵਨਾਵਾਂ ਲਿਆ ਸਕਦਾ ਹੈ: ਖ਼ੁਸ਼ੀ, ਚਿੰਤਾ, ਥਕਾਵਟ, ਸੰਵੇਦਨਸ਼ੀਲਤਾ ਜਾਂ ਹਾਵੀ ਹੋਣ ਦਾ ਅਹਿਸਾਸ। ਇਹ ਭਾਵਨਾਵਾਂ ਤੇਜ਼ੀ ਨਾਲ ਬਦਲ ਸਕਦੀਆਂ ਹਨ, ਖ਼ਾਸ ਕਰਕੇ ਉਸ ਸਮੇਂ ਜਦੋਂ ਨੀਂਦ ਅਤੇ ਰੋਜ਼ਾਨਾ ਦੀਆਂ ਆਦਤਾਂ ਬਦਲ ਰਹੀਆਂ ਹੋਣ।',
    section7Body2: 'ਕਿਸੇ ਭਰੋਸੇਯੋਗ ਵਿਅਕਤੀ ਜਾਂ ਮਾਹਿਰ ਨਾਲ ਗੱਲ ਕਰਨਾ ਮਦਦ ਕਰ ਸਕਦਾ ਹੈ, ਜਦੋਂ ਭਾਵਨਾਵਾਂ ਸੰਭਾਲਣੀਆਂ ਔਖੀਆਂ ਹੋ ਜਾਣ ਜਾਂ ਰੋਜ਼ਾਨਾ ਜ਼ਿੰਦਗੀ ਵਿੱਚ ਬਹੁਤ ਜਗ੍ਹਾ ਲੈ ਲੈਣ।',
