    section9Body: 'ਫ਼ਾਲੋ-ਅੱਪ ਮੁਲਾਕਾਤਾਂ ਸਿਹਤਯਾਬੀ, ਲੱਛਣਾਂ, ਕੰਮ ਮੁੜ ਸ਼ੁਰੂ ਕਰਨ ਅਤੇ ਬਾਕੀ ਰਹਿੰਦੇ ਸਵਾਲਾਂ ਬਾਰੇ ਗੱਲ ਕਰਨ ਦਾ ਮੌਕਾ ਹਨ। ਪਹਿਲਾਂ ਤੋਂ ਕੁਝ ਸਵਾਲ ਤਿਆਰ ਕਰ ਲੈਣ ਨਾਲ ਇਹ ਯਕੀਨੀ ਬਣਾਇਆ ਜਾ ਸਕਦਾ ਹੈ ਕਿ ਕੁਝ ਭੁੱਲਿਆ ਨਾ ਜਾਵੇ।',
