    section7Body1: 'ကလေးမွေးပြီးနောက်ကာလတွင် ပျော်ရွှင်မှု၊ စိုးရိမ်မှု၊ ပင်ပန်းနွမ်းနယ်မှု၊ စိတ်ထိခိုက်လွယ်မှု သို့မဟုတ် လွန်ကဲစွာ ဝန်ပိနေသလို ခံစားရမှုကဲ့သို့ စိတ်ခံစားချက်များစွာ ဖြစ်လာနိုင်သည်။ အထူးသဖြင့် အိပ်စက်ခြင်းနှင့် နေ့စဉ်အကျင့်များ ပြောင်းလဲနေချိန်တွင် ဤခံစားချက်များ လျင်မြန်စွာ ပြောင်းလဲနိုင်သည်။',
